import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type Device = {
  /** A unique identifier generated by the provider for initiationg device profiling. */
  sessionReference?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const deviceProperties: s.Shape<Device> = {
  sessionReference: s.optional(s.string()),
  _keysMap: {
    sessionReference: "session_reference",
  },
};

export const deviceInternalSchema: Schema<Device> = s.object<Device>(deviceProperties, {
  additionalProperties: s.json(),
});

export const deviceSchema: Schema<Device> = s.lazySchema(() =>
  s.object<Device>(
    {
      ...deviceProperties,
      sessionReference: s.optional(s.string().check(s.minLength(1), s.maxLength(255))),
    },
    { additionalProperties: s.json() },
  ),
);
